        if (!t)
            return 3;
        const pt = Studio.schedeDi(t.sub).filter(x => x.tipo === 'P').map(x => (Studio.prog(x.id) || {}).punteggio).filter(v => v != null);
        return pt.length ? voto(pt.reduce((a, b) => a + b, 0) / pt.length) : 3;
