            const rif = d.sourceRef ? [d.sourceRef.libro, d.sourceRef.capitolo && 'cap. ' + d.sourceRef.capitolo, d.sourceRef.pagina && 'p. ' + d.sourceRef.pagina].filter(Boolean).join(', ') : '';
            const dove = rif || d.r || Neuro.stepDi(d) || '';
