// ---------- CSV ----------
function csvRighe(testo) {
    const sep = (testo.split('\n')[0].match(/;/g) || []).length > (testo.split('\n')[0].match(/,/g) || []).length ? ';' : ',';
    const out = [];
    let riga = [], cella = '', virg = false;
    for (let i = 0; i < testo.length; i++) {
        const ch = testo[i];
        if (virg) {
            if (ch === '"') {
                if (testo[i + 1] === '"') {
                    cella += '"';
                    i++;
                }
                else
                    virg = false;
            }
            else
                cella += ch;
            continue;
        }
        if (ch === '"')
            virg = true;
        else if (ch === sep) {
            riga.push(cella);
            cella = '';
        }
        else if (ch === '\n' || ch === '\r') {
            if (ch === '\r' && testo[i + 1] === '\n')
                i++;
            riga.push(cella);
            cella = '';
            if (riga.some(x => x !== ''))
                out.push(riga);
            riga = [];
        }
        else
            cella += ch;
    }
    riga.push(cella);
    if (riga.some(x => x !== ''))
        out.push(riga);
    return out;
}
